import * as THREE from 'three';
import {createModel,MODEL_RATIO,layout} from './assembly-v3.js';
const $=id=>document.getElementById(id),viewport=$('viewport');
const state={mode:'transparent',opacity:.14,explode:0,selected:null,isolated:false,playing:false,angle:0,speed:.5,reverse:false,labels:true,wire:false,system:'all',cutAxis:'x',cut:0};
const orbit={theta:2.27,phi:1.12,distance:3.45,target:new THREE.Vector3(0,0,-.20)};
let model,scene,camera,renderer,drag,previous=performance.now(),toastTimer;
const clippingPlane=new THREE.Plane(new THREE.Vector3(-1,0,0),0),raycaster=new THREE.Raycaster();
function toast(msg){$('toast').hidden=false;$('toast').textContent=msg;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4200);}
function setup(){scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(36,1,.006,50);renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setClearColor(0,0);renderer.localClippingEnabled=true;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.28;viewport.appendChild(renderer.domElement);scene.add(new THREE.HemisphereLight('#c9e0e5','#354448',2.6));for(const [color,intensity,pos] of [['#fff0d5',3.5,[2,3,3]],['#c8edf1',2.5,[-3,1,-2]],['#dbecae',1.4,[0,-2,-3]]]){const light=new THREE.DirectionalLight(color,intensity);light.position.fromArray(pos);scene.add(light);}model=createModel();scene.add(model.assembly);
 const grid=new THREE.GridHelper(8,50,'#40565b','#283b40');grid.position.y=-1.50;grid.material.transparent=true;grid.material.opacity=.36;scene.add(grid);const axis=new THREE.Group();axis.position.set(-.75,-.86,-.60);for(const [v,color,name] of [[new THREE.Vector3(.15,0,0),'#c1876f','X'],[new THREE.Vector3(0,.15,0),'#a8c786','Y'],[new THREE.Vector3(0,0,.15),'#80a9bd','Z']]){const arrow=new THREE.ArrowHelper(v.clone().normalize(),new THREE.Vector3(),.15,color,.024,.012);axis.add(arrow);}scene.add(axis);
 buildList();makeLabels();applyVisuals();resize();fit();new ResizeObserver(resize).observe(viewport);renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());renderer.domElement.addEventListener('pointerdown',pointerDown);renderer.domElement.addEventListener('pointermove',pointerMove);renderer.domElement.addEventListener('pointerup',pointerUp);renderer.domElement.addEventListener('pointercancel',()=>drag=null);renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();orbit.distance=THREE.MathUtils.clamp(orbit.distance*Math.exp(e.deltaY*.001),.2,15);},{passive:false});renderer.domElement.addEventListener('dblclick',e=>{pick(e);focusPart();});viewport.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','Escape'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')orbit.theta-=.1;if(e.key==='ArrowRight')orbit.theta+=.1;if(e.key==='ArrowUp')orbit.phi=Math.max(.08,orbit.phi-.1);if(e.key==='ArrowDown')orbit.phi=Math.min(PI-.08,orbit.phi+.1);if(e.key==='+')orbit.distance*=.88;if(e.key==='-')orbit.distance*=1.12;if(e.key==='Escape')select(null);});
 $('status').textContent=`${model.parts.size} conjuntos · ${model.count.toLocaleString('es-CL')} elementos`;requestAnimationFrame(animate);
}
const PI=Math.PI;
function resize(){if(!renderer)return;renderer.setSize(viewport.clientWidth,viewport.clientHeight,false);camera.aspect=viewport.clientWidth/viewport.clientHeight;camera.updateProjectionMatrix();}
function systemVisible(p){if(state.system==='all')return true;const sets={motor:['slotLiners','windingLacing','phaseLinks','parkingHousing','parkingActuator','housing','stator','windings','rotor','cage','shaft','rotorBearing','endShields','encoder','parkingBrake','cooling'],reducer:['jointBands','outerFrame','servicePlugs','hub','spindle','shaft','hubBearing','bearingSeats','ringHigh','sunHigh','planetsHigh','carrierHigh','intermediate','ringLow','sunLow','planetsLow','carrierLow','planetBearings','thrust','seals'],supports:['spindle','hub','hubBearing','rotorBearing','bearingSeats','endShields','seals','shaft'],brakes:['parkingHousing','parkingActuator','serviceBrake','parkingBrake','spindle','shaft','cooling']};return sets[state.system]?.includes(p.id);}function buildList(){let cat='';const fragment=document.createDocumentFragment();for(const p of [...model.parts.values()].sort((a,b)=>['Estructura','Motor eléctrico','Apoyos y sellos','Reducción de alta','Reducción de baja','Reducción final','Frenos','Auxiliares','Contexto de rueda'].indexOf(a.category)-['Estructura','Motor eléctrico','Apoyos y sellos','Reducción de alta','Reducción de baja','Reducción final','Frenos','Auxiliares','Contexto de rueda'].indexOf(b.category))){if(cat!==p.category){cat=p.category;const label=document.createElement('div');label.className='category';label.textContent=cat.toUpperCase();fragment.append(label);}const row=document.createElement('div');row.className='component';row.dataset.part=p.id;const check=document.createElement('input');check.type='checkbox';check.checked=p.visible;check.setAttribute('aria-label','Mostrar '+p.name);check.addEventListener('change',()=>{p.visible=check.checked;state.isolated=false;$('isolate').textContent='Aislar pieza';applyVisuals();});const button=document.createElement('button');button.textContent=p.name;button.addEventListener('click',()=>select(p.id));const swatch=document.createElement('span');swatch.className='swatch';swatch.style.background=p.color;swatch.title=`${p.meshCount} elementos`;row.append(check,button,swatch);fragment.append(row);} $('component-list').replaceChildren(fragment);}
function makeLabels(){for(const [id,text,point] of [['windings','01 / BOBINADOS',[.37,.38,.87]],['rotor','02 / ROTOR',[-.24,.16,1.17]],['sunHigh','03 / ALTA',[.20,.36,layout.high]],['planetsLow','04 / BAJA',[-.22,.35,layout.low]],['serviceBrake','05 / FRENO',[.43,-.08,.35]],['hubBearing','06 / APOYO',[-.30,-.27,-.865]]]){const el=document.createElement('span');el.className='model-label';el.textContent=text;el.dataset.part=id;el.dataset.point=JSON.stringify(point);$('model-labels').append(el);}}
function applyVisuals(){if(!model)return;clippingPlane.normal.set(state.cutAxis==='x'?-1:0,state.cutAxis==='y'?-1:0,state.cutAxis==='z'?-1:0);clippingPlane.constant=state.cut*(state.cutAxis==='z'?2.8:.75);for(const p of model.parts.values()){p.group.visible=p.visible&&systemVisible(p)&&(!state.isolated||p.id===state.selected);p.group.position.z=p.base+state.explode*p.explosion;p.meshes.forEach(m=>{const mat=m.material;let alpha=p.shell?(state.mode==='solid'?1:state.opacity):1;if(state.mode==='transparent'&&!state.isolated){if(p.id==='stator')alpha=.22;if(p.id==='rotor')alpha=.48;if(['carrierHigh','carrierLow'].includes(p.id))alpha=.28;if(m.userData.role==='separator')alpha=state.opacity;}if(state.mode==='cut')alpha=1;if(state.isolated)alpha=1;mat.opacity=alpha;mat.transparent=alpha<1;mat.depthWrite=alpha>=.98;mat.wireframe=state.wire;mat.clippingPlanes=state.mode==='cut'?[clippingPlane]:[];mat.emissive.set(p.id===state.selected?'#486529':'#000000');mat.emissiveIntensity=p.id===state.selected?.24:0;m.visible=!(m.userData.role==='lamination'&&state.mode==='transparent'&&!state.isolated);mat.needsUpdate=true;});const row=document.querySelector(`.component[data-part="${p.id}"]`);row?.classList.toggle('active',p.id===state.selected);if(row)row.querySelector('input').checked=p.visible;}
 for(const p of model.parts.values())for(const child of p.group.children){if(child.userData.follows){const host=model.parts.get(child.userData.follows);child.position.z=child.userData.baseZ+state.explode*host.explosion;}}$('exterior-view').value=model.parts.get('outerFrame').visible?'cimetp':'reference';$('opacity').disabled=state.mode==='cut';$('cut-controls').hidden=state.mode!=='cut';$('opacity-label').textContent=Math.round(state.opacity*100)+' %';$('explode-label').textContent=Math.round(state.explode*100)+' %';$('cut-label').textContent=Math.round(state.cut*100)+' %';document.querySelectorAll('[data-mode]').forEach(b=>{const active=b.dataset.mode===state.mode;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}
function select(id){state.selected=id;state.isolated=false;if(id&&state.system!=='all'){state.system='all';$('system-view').value='all';}$('isolate').textContent='Aislar pieza';const p=model.parts.get(id);$('isolate').disabled=!p;$('focus').disabled=!p;$('part-number').textContent=p?String(p.number).padStart(2,'0'):'WM';$('part-name').textContent=p?.name||'Ensamble completo';$('part-evidence').textContent=p?.evidence||'Reconstrucción de referencia';$('part-description').textContent=p?.description||'Selecciona una pieza en el modelo o en la lista para explorar su función, sus detalles y su procedencia.';const details=p?[['Detalle geométrico',p.detail],['Extensión aproximada · X / Y / Z',[p.dimensions.x,p.dimensions.y,p.dimensions.z].map(x=>Math.round(x*1000)+' mm').join(' / ')],['Elementos visibles',p.meshCount+' geometrías'],['Procedencia',p.source]]:[['Motor documentado','Inducción AC · GDY106'],['Reducción publicada','32,62 : 1'],['Aceite por reductor','95 L']];$('part-reference').hidden=!referenceFor(id);$('part-details').replaceChildren(...details.map(([title,value])=>{const d=document.createElement('div');d.className='detail';const a=document.createElement('span');a.textContent=title;const b=document.createElement('b');b.textContent=value;d.append(a,b);return d;}));if(p&&!p.visible){p.visible=true;toast('Componente visible: '+p.name);}applyVisuals();}
function pointerDown(e){drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,pan:e.shiftKey||e.button===2,id:e.pointerId};renderer.domElement.setPointerCapture(e.pointerId);}
function pointerMove(e){if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(drag.pan){const right=new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld,0),up=new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld,1);orbit.target.addScaledVector(right,-dx*.0008*orbit.distance).addScaledVector(up,dy*.0008*orbit.distance);}else{orbit.theta-=dx*.006;orbit.phi=THREE.MathUtils.clamp(orbit.phi+dy*.006,.06,PI-.06);}drag.x=e.clientX;drag.y=e.clientY;}
function pointerUp(e){if(drag&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<4)pick(e);drag=null;}
function clipped(point){return state.mode==='cut'&&clippingPlane.distanceToPoint(point)<0;}
function pick(e){const r=renderer.domElement.getBoundingClientRect();raycaster.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const targets=[];for(const p of model.parts.values())if(p.group.visible&&(!p.shell||state.mode!=='transparent'||state.opacity>=.30))targets.push(...p.meshes.filter(m=>m.visible&&m.material.opacity>.30));const hit=raycaster.intersectObjects(targets,false).find(h=>!clipped(h.point));select(hit?.object.userData.part||null);}
function visibleBounds(){const box=new THREE.Box3();for(const p of model.parts.values())if(p.group.visible)box.union(new THREE.Box3().setFromObject(p.group));return box;}
function fit(){const box=visibleBounds();if(box.isEmpty())return;const sphere=box.getBoundingSphere(new THREE.Sphere());orbit.target.copy(sphere.center);const fov=Math.min(camera.fov*PI/180,2*Math.atan(Math.tan(camera.fov*PI/360)*camera.aspect));orbit.distance=Math.max(.5,sphere.radius/Math.sin(fov/2)*1.03);}
function focusPart(){const p=model.parts.get(state.selected);if(!p)return;model.assembly.updateMatrixWorld(true);const box=new THREE.Box3().setFromObject(p.group);const sphere=box.getBoundingSphere(new THREE.Sphere());orbit.target.copy(sphere.center);orbit.distance=Math.max(.28,sphere.radius*3.8);}
function setView(view){if(view==='iso'){orbit.theta=2.27;orbit.phi=1.12;}if(view==='front'){orbit.theta=PI;orbit.phi=PI/2;}if(view==='rear'){orbit.theta=0;orbit.phi=PI/2;}if(view==='side'){orbit.theta=PI/2;orbit.phi=PI/2;}fit();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function updateLabels(){const boxes=[];for(const el of $('model-labels').children){const p=model.parts.get(el.dataset.part);const point=new THREE.Vector3().fromArray(JSON.parse(el.dataset.point));point.z+=state.explode*p.explosion;const hidden=!state.labels||!p.group.visible||clipped(point);if(hidden){el.hidden=true;continue;}point.project(camera);el.hidden=point.z>1||Math.abs(point.x)>.87||Math.abs(point.y)>.7;if(el.hidden)continue;let x=(point.x+1)/2*viewport.clientWidth,y=(-point.y+1)/2*viewport.clientHeight;const w=el.offsetWidth||92;for(let i=0;i<6;i++){if(!boxes.some(b=>Math.abs(x-b.x)<(w+b.w)/2+4&&Math.abs(y-b.y)<26))break;y+=28;}boxes.push({x,y,w});el.style.left=x+'px';el.style.top=y+'px';}}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.06,(now-previous)/1000);previous=now;if(state.playing){state.angle+=dt*state.speed*1.8*(state.reverse?-1:1);for(const motion of model.motions)motion.object.rotation.z=state.angle*motion.ratio+(motion.phase||0);}camera.position.set(orbit.target.x+orbit.distance*Math.sin(orbit.phi)*Math.sin(orbit.theta),orbit.target.y+orbit.distance*Math.cos(orbit.phi),orbit.target.z+orbit.distance*Math.sin(orbit.phi)*Math.cos(orbit.theta));camera.lookAt(orbit.target);renderer.render(scene,camera);updateLabels();}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function exportGLB(){const b=$('export');b.disabled=true;b.textContent='Exportando…';try{const {GLTFExporter}=await import('./vendor/GLTFExporter.js');const clone=model.assembly.clone(true);clone.userData={...model.assembly.userData,explosion:state.explode,note:'Static geometry. Clip planes and visual motion not exported.'};const exporter=new GLTFExporter();const result=await exporter.parseAsync(clone,{binary:true,onlyVisible:true});download(new Blob([result],{type:'model/gltf-binary'}),'wheel-motor-gdy106-revision-03.glb');toast('GLB descargado con la geometría y visibilidad actuales.');}catch(e){console.error(e);toast('No se pudo exportar el GLB. '+e.message);}finally{b.disabled=false;b.textContent='Descargar GLB ↓';}}
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{state.mode=b.dataset.mode;applyVisuals();}));$('opacity').addEventListener('input',e=>{state.opacity=Number(e.target.value)/100;if(state.mode==='solid')state.mode='transparent';applyVisuals();});$('explode').addEventListener('input',e=>{state.explode=Number(e.target.value)/100;applyVisuals();fit();});$('cut').addEventListener('input',e=>{state.cut=Number(e.target.value)/100;applyVisuals();});$('cut-axis').addEventListener('change',e=>{state.cutAxis=e.target.value;applyVisuals();});$('labels').addEventListener('change',e=>state.labels=e.target.checked);$('wire').addEventListener('change',e=>{state.wire=e.target.checked;applyVisuals();});$('show-all').addEventListener('click',()=>{for(const p of model.parts.values())p.visible=!['rims','tires','outerFrame'].includes(p.id);state.system='all';$('system-view').value='all';select(null);applyVisuals();fit();});$('search').addEventListener('input',e=>{const q=e.target.value.toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'');document.querySelectorAll('.component').forEach(r=>r.hidden=!r.textContent.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q));document.querySelectorAll('.category').forEach(r=>r.hidden=!!q);});$('isolate').addEventListener('click',()=>{state.isolated=!state.isolated;$('isolate').textContent=state.isolated?'Ver ensamble':'Aislar pieza';applyVisuals();if(state.isolated)focusPart();else fit();});$('focus').addEventListener('click',focusPart);$('play').addEventListener('click',()=>{state.playing=!state.playing;$('play').textContent=state.playing?'Ⅱ Pausar mecanismo':'▷ Animar mecanismo';$('play').setAttribute('aria-pressed',String(state.playing));});$('speed').addEventListener('input',e=>{state.speed=Number(e.target.value)/100;$('speed-label').textContent=state.speed.toLocaleString('es-CL')+'×';});$('reverse').addEventListener('change',e=>state.reverse=e.target.checked);document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$('fit').addEventListener('click',fit);$('snapshot').addEventListener('click',()=>{renderer.render(scene,camera);renderer.domElement.toBlob(b=>{if(b)download(b,'wheel-motor-inspeccion.png');});});$('export').addEventListener('click',exportGLB);$('sources-open').addEventListener('click',()=>$('sources-dialog').showModal());$('sources-close').addEventListener('click',()=>$('sources-dialog').close());$('reference-open').addEventListener('click',()=>openReference('assets/reference-930e4.png','Fotografía aportada · rótulo 930E-4; variante de motor sin placa autenticada'));$('image-close').addEventListener('click',()=>$('image-dialog').close());for(const id of ['sources-dialog','image-dialog','variants-dialog'])$(id).addEventListener('click',e=>{if(e.target===$(id)){const r=$(id).getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$(id).close();}});

const referenceMap={housing:['assets/reference-930e4.png','Fotografía aportada · rótulo 930E-4'],flange:['assets/cimetp-49.jpg','CIMETP · 00:49 · brida y campana'],jointBands:['assets/cimetp-49.jpg','CIMETP · 00:49 · uniones exteriores'],outerFrame:['assets/cimetp-69.jpg','CIMETP · 01:09 · tambor exterior; variante indeterminada'],liftingLugs:['assets/exterior.png','i2.png · orejas exteriores'],slotLiners:['assets/maintenance-lacing.jpg','Mantenimiento · 01:30:00 · embarrilado'],windingLacing:['assets/maintenance-lacing.jpg','Mantenimiento · 01:30:00 · amarres de bobinado'],windings:['assets/maintenance-lacing.jpg','Mantenimiento · 01:30:00 · cabezas de bobina'],encoder:['assets/encoder-reference.png','Mantenimiento · 01:25:27 · captador y rueda dentada'],spindle:['assets/maintenance-detail.jpg','Mantenimiento · 00:16:00 · corte mecánico'],shaft:['assets/maintenance-detail.jpg','Mantenimiento · 00:16:00 · eje y reductor']};
